def transform(grid):
    h=len(grid); w=len(grid[0]); out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]; colors=set()
            for y,x in q:
                comp.append((y,x))
                if grid[y][x] not in (0,1): colors.add(grid[y][x])
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
